def get_comments(lang):
    if lang in LANG_COMMENTS:
        return LANG_COMMENTS[lang]
    # Handle min/gen suffix: e.g., "JavaScript (min)" -> base "JavaScript"
    base = lang.split(" (")[0]
    if base in LANG_COMMENTS:
        return LANG_COMMENTS[base]
    # Fallback: try generic C-like for code languages, empty for text-like?
    # For safety, return C-like (// + /*) as most code languages use it; text-like will just not have those tokens in typical files
    # But to avoid misclassifying # in C-like fallback, we return only // and /* (not #)
    # This means Python-like unknown (e.g., Lua fallback?) would miss -- comments. However unknown rarely tested.
    # We'll return // + /* as fallback.
    return {"line": ["//"], "block": [("/*","*/")]}

# Extension to language detection
def detect_language(filepath, content_bytes=None):
    # filepath is string path
    basename = os.path.basename(filepath)
    lower_base = basename.lower()
    # Check count-as remap later (handled outside)
    # 1. Exact filename matches for special languages
    # Build checks: if lower_base in EXT_MAP and EXT_MAP[lower_base] is a language where ext equals filename?
    # Actually EXT_MAP contains both extensions and filenames (like makefile, dockerfile, etc.)
    # Check basename exact
    if lower_base in EXT_MAP:
        # But need to distinguish: e.g., "Makefile" basename is "makefile" which is in map -> Makefile. Good.
        # For "test.go", basename "test.go" not in map, so fall through to extension.
        return EXT_MAP[lower_base]
    # Check for compound extensions like d.ts, build.bazel, meson.build, etc.
    # Sort keys by length desc and check suffix
    # For efficiency, precompute sorted keys? Do on demand for now.
    # Check if filename ends with .<ext> for exts containing .
    for ext_key in sorted(EXT_MAP.keys(), key=len, reverse=True):
        if '.' in ext_key:
            if lower_base.endswith(ext_key) or lower_base.endswith('.'+ext_key):
                # e.g., ext "d.ts" and file "foo.d.ts" -> ends with "d.ts" true
                # e.g., ext "cmakelists.txt" and file "cmakelists.txt" -> true
                # Need to ensure match is at boundary: either exact or dot before?
                # For "build.bazel" and file "foo.build.bazel"? Unclear. We'll just check endswith.
                return EXT_MAP[ext_key]
            # Also check for exact like "meson.build" file named "meson.build"
            if lower_base == ext_key:
                return EXT_MAP[ext_key]
    # 2. Extension check (after last dot)
    if '.' in basename:
        ext = basename.rsplit('.', 1)[-1].lower()
        # Handle .d.ts special: if ends with .d.ts, ext would be "ts", but should be "d.ts"
        if lower_base.endswith('.d.ts'):
            if 'd.ts' in EXT_MAP:
                return EXT_MAP['d.ts']
        if ext in EXT_MAP:
            return EXT_MAP[ext]
        # Try lower ext with dot? e.g., "cs.st" for Smalltalk? File "foo.cs.st"? ext after last dot is "st", not "cs.st". Need to handle.
        # Check for two-part exts
        parts = lower_base.split('.')
        if len(parts) >= 3:
            two = '.'.join(parts[-2:])
            if two in EXT_MAP:
                return EXT_MAP[two]
    else:
        # No extension: try shebang if content available
        pass
    # 3. No extension or unknown extension: try shebang
    if content_bytes is not None:
        try:
            head = content_bytes[:512].decode('utf-8', errors='ignore')
            first_line = head.splitlines()[0] if head.splitlines() else ""
            if first_line.startswith('#!'):
                low = first_line.lower()
                if 'python' in low:
                    return 'Python'
                if 'bash' in low or 'sh' in low:
                    # Distinguish bash vs sh? scc detected "#!/bin/bash" as BASH? Let's check: script with #!/bin/bash gave BASH earlier.
                    if 'bash' in low:
                        return 'BASH'
                    return 'Shell'
                if 'zsh' in low:
                    return 'Zsh'
                if 'fish' in low:
                    return 'Fish'
                if 'perl' in low:
                    return 'Perl'
                if 'ruby' in low:
                    return 'Ruby'
                if 'node' in low or 'js' in low:
                    return 'JavaScript'
                if 'php' in low:
                    return 'PHP'
                if 'lua' in low:
                    return 'Lua'
                if 'awk' in low:
                    return 'AWK'
                if 'tcl' in low or 'wish' in low:
                    return 'TCL'
                if 'ksh' in low:
                    return 'Korn Shell'
                if 'csh' in low:
                    return 'C Shell'
                if 'pwsh' in low or 'powershell' in low:
                    return 'Powershell'
        except:
            pass
    return None

