# Counting logic - clean implementation
def count_file(filepath, language, content_bytes, no_complexity=False):
    nbytes = len(content_bytes)
    if nbytes == 0:
        return {"Lines":0,"Code":0,"Comment":0,"Blank":0,"Complexity":0,"Bytes":0}
    try:
        text = content_bytes.decode('utf-8', errors='ignore')
    except:
        text = ""
    raw_lines = text.split('\n')
    if text.endswith('\n'):
        raw_lines = raw_lines[:-1]
    lines = [l.rstrip('\r') for l in raw_lines]
    comments_def = get_comments(language)
    line_comments = sorted(comments_def.get("line", []), key=len, reverse=True)
    block_comments = sorted(comments_def.get("block", []), key=lambda x: len(x[0]), reverse=True)
    is_python = (language == "Python" or language.startswith("Python"))
    complexity_keywords = [] if no_complexity else get_complexity_keywords(language)
    total_code = 0
    total_comment = 0
    total_blank = 0
    total_complexity = 0
    in_block = None  # (start, end)
