        try:
            parts=pt.split(",")
            a=float(parts[1]); b=float(parts[2]); c=float(parts[3]); d=float(parts[4])
            return (a,b,c,d,pt)
        except:
            return (2.4,1.05,2.5,0.38,"organic")
    # unknown -> organic? Observed invalid cocomo type still shows organic and no error.
    return (2.4,1.05,2.5,0.38,"organic")

def compute_cocomo(total_code, avg_wage, eaf, overhead, project_type):
    import math
    a,b,c,d,label=cocomo_params(project_type)
    ksloc=total_code/1000.0
    if ksloc==0:
        effort=0.0
    else:
        effort=a*(math.pow(ksloc,b))*eaf
    if effort==0:
        sched=0.0
    else:
        sched=c*math.pow(effort,d)
    people=0.0 if sched==0 else effort/sched
    # cost with integer division quirk: avg_wage is int, wage/12 integer division in Go?
    try:
        wage_int=int(avg_wage)
    except:
        wage_int=int(float(avg_wage))
    monthly=wage_int//12
    cost=float(effort*monthly*overhead)
    return {"effort":effort,"schedule":sched,"people":people,"cost":cost,"label":label,"a":a,"b":b,"c":c,"d":d}

def format_cost_int(cost):
    # truncate to int and format with commas
    iv=int(cost)  # truncates toward zero, same as Go int()?
    return f"{iv:,}"

# Size formatting
def format_size_unit(unit):
    u=unit.lower()
    mapping={
        "si":"SI","binary":"BINARY","mixed":"MIXED",
        "xkcd-kb":"XKCD-KB","xkcd-kelly":"XKCD-KELLY","xkcd-imaginary":"XKCD-IMAGINARY",
        "xkcd-intel":"XKCD-INTEL","xkcd-drive":"XKCD-DRIVE","xkcd-bakers":"XKCD-BAKERS"
    }
    return mapping.get(u,"SI")

def format_bytes_megabytes(total_bytes, unit):
    # scc shows "Processed X bytes, Y megabytes (UNIT)"
    # Y is total_bytes / 1e6? Or / 2**20? Depends on unit? Let's probe: for 15 bytes, shows 0.000. For 40000 bytes, shows 0.040 (SI) vs? For binary, 40000 bytes would be 40000/1048576=0.038? Let's test.
